"use strict";

/* Desktop Help (`doc/fim-gui-help-design.md`).
 *
 * Help home lists the registered topics from `help/topics.json`; each
 * topic is a pre-rendered fragment, `help/<topic>.html`, generated by
 * `dev/bin/generate-help-html` from `doc/help-topics.json`. Back and
 * Forward move between Help pages. Return to work, and Back on the first
 * page, go to the screen and tab Help was opened from. F1 opens the topic
 * for the focused Configure field, or for the visible screen.
 */

const helpContent = document.getElementById("help-content");
const helpBreadcrumb = document.getElementById("help-breadcrumb");
const helpBackButton = document.getElementById("help-back-button");
const helpForwardButton = document.getElementById("help-forward-button");
const helpHomeButton = document.getElementById("help-home-button");
const helpScreenButton = document.getElementById("help-screen-button");
const helpReturnButton = document.getElementById("help-return-button");
const helpSearch = document.getElementById("help-search");

const HELP_HOME_SCREEN = "screen-open-run";
const SEARCH_RESULT_LIMIT = 40;
const SEARCH_DEBOUNCE_MS = 150;
const SNIPPET_RADIUS = 80;

// Screen-to-topic map for F1 and "Help for this screen". Every anchor is
// checked against the generated fragments by `test_help_html.py`.
const SCREEN_HELP = {
    "screen-open-run": { topic: "gui-organize", anchor: "", label: "Home" },
    "screen-configure": { topic: "gui-configure", anchor: "", label: "Configure" },
    "screen-run": { topic: "gui-run-results", anchor: "", label: "Run and results" },
    "screen-explore": { topic: "gui-explore", anchor: "", label: "Explore" },
    "screen-sweep": { topic: "gui-sweeps", anchor: "results", label: "Sweep results" },
    "screen-sweep-compare": {
        topic: "gui-compare",
        anchor: "compare-sweeps",
        label: "Compare sweeps",
    },
    "screen-compare": { topic: "gui-compare", anchor: "compare-runs", label: "Compare runs" },
};

const configurationAnchor = (anchor) => ({ topic: "configuration", anchor });

// `FIELD_HELP` key (`field-help.js`) to topic and anchor for F1. A test
// checks that every `FIELD_HELP` key has an entry here and that every
// anchor exists, so a new field cannot ship without a reference target.
const FIELD_HELP_TOPICS = {
    N: configurationAnchor("n"),
    d: configurationAnchor("d"),
    seed: configurationAnchor("seed"),
    ploidy: configurationAnchor("ploidy"),
    n_mode: configurationAnchor("n"),
    m_mode: configurationAnchor("m"),
    m_rate: configurationAnchor("m"),
    m_topology: configurationAnchor("sparse-and-spatial-stepping-stone-migration"),
    m_topology_rate: configurationAnchor("sparse-and-spatial-stepping-stone-migration"),
    m_topology_rows: configurationAnchor("sparse-and-spatial-stepping-stone-migration"),
    m_topology_columns: configurationAnchor("sparse-and-spatial-stepping-stone-migration"),
    mu_mode: configurationAnchor("mu"),
    mu_value: configurationAnchor("mu"),
    mu_b_value: configurationAnchor("deriving-mu-from-a-per-base-rate"),
    migrant_sampling: configurationAnchor("migrant_sampling"),
    mutation_model: configurationAnchor("mutation_model"),
    deme_weighting: configurationAnchor("deme_weighting"),
    loci_mode: configurationAnchor("loci-1"),
    locus_lengths: configurationAnchor("loci-1"),
    initial_conditions_mode: configurationAnchor("initial-conditions"),
    initial_allele_count: configurationAnchor("initial_allele_count"),
    initial_concentration: configurationAnchor("initial_concentration"),
    equilibrium_convergence_window: configurationAnchor(
        "equilibrium_convergence_window-equilibrium_convergence_tolerance-equilibrium_max_generations"
    ),
    equilibrium_convergence_tolerance: configurationAnchor(
        "equilibrium_convergence_window-equilibrium_convergence_tolerance-equilibrium_max_generations"
    ),
    equilibrium_max_generations: configurationAnchor(
        "equilibrium_convergence_window-equilibrium_convergence_tolerance-equilibrium_max_generations"
    ),
    cs_group: configurationAnchor("convergence_statistic"),
    convergence_combinator: configurationAnchor("convergence_combinator"),
    convergence_burn_in: configurationAnchor("convergence_burn_in"),
    convergence_estimate: configurationAnchor("convergence_estimate"),
    statistic_precision: configurationAnchor("statistic_precision"),
    precision_method: configurationAnchor("precision_method"),
    replicate_averaging_window: configurationAnchor("replicate_averaging_window"),
    trajectory_retention: configurationAnchor(
        "trajectory_retention-trajectory_stride-trajectory_thinning_start-trajectory_keep_last-trajectory_keep_burn_in"
    ),
    trajectory_stride: configurationAnchor(
        "trajectory_retention-trajectory_stride-trajectory_thinning_start-trajectory_keep_last-trajectory_keep_burn_in"
    ),
    trajectory_thinning_start: configurationAnchor(
        "trajectory_retention-trajectory_stride-trajectory_thinning_start-trajectory_keep_last-trajectory_keep_burn_in"
    ),
    precision: configurationAnchor("precision"),
    max_generations: configurationAnchor("max_generations"),
    engine_backend: configurationAnchor("engine_backend"),
    n_replicates: configurationAnchor("n_replicates"),
    stop_batch_early: configurationAnchor("stop_batch_early"),
    replicate_minimum: configurationAnchor("replicate_minimum"),
    confidence: configurationAnchor("confidence"),
    max_workers: { topic: "gui-settings", anchor: "background-work" },
    max_concurrent_replicates: configurationAnchor("max_concurrent_replicates"),
    jit: configurationAnchor("jit"),
    auto_vector_min_d: configurationAnchor("auto_vector_min_d"),
    auto_vector_max_capacity: configurationAnchor("auto_vector_max_capacity"),
    significant_digits: { topic: "gui-settings", anchor: "startup-and-display" },
    dark_mode_override: { topic: "gui-settings", anchor: "startup-and-display" },
};

// Help-page history, reset each time Help is entered. An entry's topic
// is `null` for Help home.
let pages = [];
let pageIndex = -1;
// Where Help was opened from: `{tabId, screenId}`.
let origin = { tabId: null, screenId: HELP_HOME_SCREEN };
// Each render takes a token; a slower, older fetch never overwrites a
// newer page. `window.__fimHelpRendered` names what finished rendering
// (a topic id, "home", "search", "error", or "tab-closed") so tests wait
// on a fact rather than on time.
let renderToken = 0;
let manifestPromise = null;
let searchIndexPromise = null;
let searchTimer = null;

/**
 * Fetch a bundled Help file, rejecting on any non-success status.
 *
 * @param {string} path - Path below `help/`.
 * @param {"text"|"json"} kind - How to read the body.
 * @returns {Promise<string|object>}
 */
async function fetchHelpFile(path, kind) {
    const response = await fetch(`help/${path}`);
    if (!response.ok) {
        throw new Error(`help/${path}: ${response.status}`);
    }
    return kind === "json" ? response.json() : response.text();
}

/** @returns {Promise<object>} The cached topic manifest. */
function loadManifest() {
    if (manifestPromise === null) {
        manifestPromise = fetchHelpFile("topics.json", "json").catch((error) => {
            manifestPromise = null;
            throw error;
        });
    }
    return manifestPromise;
}

/** @returns {Promise<object[]>} The cached section search index. */
function loadSearchIndex() {
    if (searchIndexPromise === null) {
        searchIndexPromise = fetchHelpFile("search-index.json", "json").catch((error) => {
            searchIndexPromise = null;
            throw error;
        });
    }
    return searchIndexPromise;
}

/**
 * Create an element with optional class and text.
 *
 * @param {string} tag
 * @param {string} [className]
 * @param {string} [text]
 * @returns {HTMLElement}
 */
function element(tag, className, text) {
    const node = document.createElement(tag);
    if (className) {
        node.className = className;
    }
    if (text !== undefined) {
        node.textContent = text;
    }
    return node;
}

/**
 * Create a link that the delegated click handler opens in Help.
 *
 * @param {string} topic
 * @param {string} anchor
 * @param {string} text
 * @returns {HTMLAnchorElement}
 */
function topicLink(topic, anchor, text) {
    const link = element("a", "", text);
    link.href = "#";
    link.dataset.fimHelp = topic;
    link.dataset.fimAnchor = anchor;
    return link;
}

/** @returns {string|null} The id of the visible top-level screen. */
function visibleScreenId() {
    const visible = document.querySelector(".screen:not([hidden])");
    return visible === null ? null : visible.id;
}

/** Record where Help was opened from, unless Help is already showing. */
function captureOrigin() {
    const screenId = visibleScreenId();
    if (screenId === "screen-help") {
        return;
    }
    origin = {
        tabId: window.fim.workspace.selectedId(),
        screenId: screenId ?? HELP_HOME_SCREEN,
    };
    pages = [];
    pageIndex = -1;
    helpSearch.value = "";
    const screenHelp = SCREEN_HELP[origin.screenId];
    helpScreenButton.hidden = screenHelp === undefined;
    if (screenHelp !== undefined) {
        helpScreenButton.textContent = `Help for ${screenHelp.label}`;
    }
}

/** Enable Forward only when there is a later Help page. */
function syncHelpButtons() {
    helpForwardButton.disabled = pageIndex >= pages.length - 1;
}

/**
 * Add a page after the current one, dropping any forward pages.
 *
 * @param {string|null} topic
 * @param {string} anchor
 */
function pushPage(topic, anchor) {
    pages = pages.slice(0, pageIndex + 1);
    pages.push({ topic, anchor });
    pageIndex = pages.length - 1;
}

/**
 * Show the breadcrumb: Help, then the topic's group and title.
 *
 * @param {object|null} topicInfo - The manifest entry, or null for home.
 * @param {string} [groupTitle]
 * @param {string} [fallbackTitle] - Shown when no manifest entry exists.
 */
function renderBreadcrumb(topicInfo, groupTitle, fallbackTitle) {
    helpBreadcrumb.replaceChildren();
    if (topicInfo === null && fallbackTitle === undefined) {
        helpBreadcrumb.append(element("span", "help-breadcrumb-current", "Help"));
        return;
    }
    const home = element("a", "", "Help");
    home.href = "#";
    home.dataset.fimHelpHome = "";
    helpBreadcrumb.append(home);
    for (const part of [groupTitle, topicInfo?.title ?? fallbackTitle]) {
        if (part) {
            helpBreadcrumb.append(element("span", "help-breadcrumb-separator", "›"));
            helpBreadcrumb.append(element("span", "help-breadcrumb-current", part));
        }
    }
}

/**
 * Scroll to an anchor in the shown page, or to the top.
 *
 * @param {string} anchor
 */
function scrollToAnchor(anchor) {
    const target = anchor ? document.getElementById(anchor) : null;
    if (target !== null && helpContent.contains(target)) {
        target.scrollIntoView();
    } else {
        helpContent.scrollTop = 0;
    }
}

/**
 * Show a load failure with Retry, Help home, and Return to work.
 *
 * @param {string} message
 * @param {Function} retry
 */
function renderError(message, retry) {
    const panel = element("div", "help-error");
    panel.setAttribute("role", "alert");
    panel.append(element("h1", "", "This Help page could not be loaded"));
    panel.append(element("p", "", message));
    const actions = element("div", "actions");
    const retryButton = element("button", "", "Try again");
    retryButton.type = "button";
    retryButton.addEventListener("click", retry);
    const homeButton = element("button", "", "Help home");
    homeButton.type = "button";
    homeButton.addEventListener("click", () => window.fim.showHelpHome());
    const returnButton = element("button", "", "Return to work");
    returnButton.type = "button";
    returnButton.addEventListener("click", returnToWork);
    actions.append(retryButton, homeButton, returnButton);
    panel.append(actions);
    helpContent.replaceChildren(panel);
    window.__fimHelpRendered = "error";
}

/** Build Help home from the topic manifest. */
async function renderHome() {
    const token = ++renderToken;
    window.__fimHelpRendered = null;
    renderBreadcrumb(null);
    let manifest;
    try {
        manifest = await loadManifest();
    } catch (error) {
        if (token === renderToken) {
            renderError(String(error.message), renderHome);
        }
        return;
    }
    if (token !== renderToken) {
        return;
    }
    const page = element("div", "help-home");
    page.append(element("h1", "", "Help"));
    const intro = element("p", "help-home-intro");
    intro.append(
        "Desktop help for fim, bundled with the app. Before comparing results " +
            "with published values, check the "
    );
    intro.append(topicLink("gui-conventions", "", "implementation conventions"));
    intro.append(". Press F1 in a Configure field for its reference entry.");
    page.append(intro);
    for (const group of manifest.groups) {
        const topics = manifest.topics.filter((topic) => topic.group === group.id);
        const section = element("section", "help-home-group");
        section.append(element("h2", "", group.title));
        const list = element("ul", "help-topic-list");
        for (const topic of topics) {
            const item = element("li");
            item.append(topicLink(topic.id, "", topic.title));
            item.append(element("span", "help-topic-summary", topic.summary));
            list.append(item);
        }
        section.append(list);
        page.append(section);
    }
    helpContent.replaceChildren(page);
    helpContent.scrollTop = 0;
    window.__fimHelpRendered = "home";
}

/**
 * Fetch and show one topic fragment, then scroll to its anchor.
 *
 * @param {string} topic
 * @param {string} anchor
 */
async function renderTopic(topic, anchor) {
    const token = ++renderToken;
    window.__fimHelpRendered = null;
    let fragment;
    try {
        fragment = await fetchHelpFile(`${topic}.html`, "text");
    } catch (error) {
        if (token === renderToken) {
            renderBreadcrumb(null, undefined, topic);
            renderError(String(error.message), () => renderTopic(topic, anchor));
        }
        return;
    }
    if (token !== renderToken) {
        return;
    }
    helpContent.innerHTML = fragment;
    scrollToAnchor(anchor);
    window.__fimHelpRendered = topic;
    try {
        const manifest = await loadManifest();
        if (token !== renderToken) {
            return;
        }
        const info = manifest.topics.find((entry) => entry.id === topic) ?? null;
        const group = manifest.groups.find((entry) => entry.id === info?.group);
        renderBreadcrumb(info, group?.title, topic);
    } catch {
        renderBreadcrumb(null, undefined, topic);
    }
}

/** Show the current Help page. */
function renderCurrentPage() {
    syncHelpButtons();
    const page = pages[pageIndex];
    if (page.topic === null) {
        renderHome();
    } else {
        renderTopic(page.topic, page.anchor);
    }
}

/**
 * Leave Help for the screen and tab it was opened from.
 *
 * Uses the tab's own screen history when Help is its current entry, so
 * tab-level Back and Forward stay consistent. When the tab has closed,
 * explains that and offers Home.
 */
function returnToWork() {
    const workspace = window.fim.workspace;
    const { tabId, screenId } = origin;
    if (tabId !== null && workspace.get(tabId) === null) {
        renderTabClosed();
        return;
    }
    if (tabId !== null && workspace.selectedId() !== tabId) {
        window.fim.activateWorkspaceDocument(tabId);
        return;
    }
    const state = tabId === null ? null : workspace.get(tabId);
    if (state !== null && state.history[state.historyIndex] === "screen-help") {
        const previous = state.history[state.historyIndex - 1];
        if (previous === screenId) {
            window.fim.navigateBack();
            return;
        }
    }
    window.fim.showScreen(screenId);
}

/** Explain that the origin tab closed and offer Home. */
function renderTabClosed() {
    renderToken++;
    const panel = element("div", "help-error");
    panel.setAttribute("role", "status");
    panel.append(element("h1", "", "The document you came from is closed"));
    panel.append(
        element(
            "p",
            "",
            "Help was opened from a tab that has since closed. Saved runs " +
                "remain on Home."
        )
    );
    const actions = element("div", "actions");
    const homeButton = element("button", "", "Go to Home");
    homeButton.type = "button";
    homeButton.addEventListener("click", () => {
        origin = { tabId: null, screenId: HELP_HOME_SCREEN };
        window.fim.showScreen(HELP_HOME_SCREEN);
    });
    actions.append(homeButton);
    panel.append(actions);
    helpContent.replaceChildren(panel);
    window.__fimHelpRendered = "tab-closed";
}

/**
 * Score one search entry; 0 means some term does not match.
 *
 * @param {object} entry - A `search-index.json` entry.
 * @param {string[]} terms - Lowercase query terms.
 * @param {string} phrase - The whole lowercase query.
 * @param {Map<string, object>} topics - Manifest topics by id.
 * @returns {number}
 */
function scoreEntry(entry, terms, phrase, topics) {
    const topic = topics.get(entry.topic);
    const heading = entry.heading.toLowerCase();
    const text = entry.text.toLowerCase();
    const meta = topic
        ? `${topic.title} ${topic.aliases.join(" ")}`.toLowerCase()
        : "";
    let score = 0;
    for (const term of terms) {
        if (heading.includes(term)) {
            score += 5;
        } else if (meta.includes(term)) {
            score += 3;
        } else if (text.includes(term)) {
            score += 1;
        } else {
            return 0;
        }
    }
    if (heading.includes(phrase)) {
        score += 5;
    }
    if (topic?.group === "desktop") {
        score += 2;
    }
    return score;
}

/**
 * Return a short excerpt of `text` around the first matching term.
 *
 * @param {string} text
 * @param {string[]} terms
 * @returns {string}
 */
function snippet(text, terms) {
    const lower = text.toLowerCase();
    const positions = terms.map((term) => lower.indexOf(term)).filter((at) => at >= 0);
    const at = positions.length > 0 ? Math.min(...positions) : 0;
    const start = Math.max(0, at - SNIPPET_RADIUS);
    const end = Math.min(text.length, at + SNIPPET_RADIUS);
    return `${start > 0 ? "…" : ""}${text.slice(start, end)}${end < text.length ? "…" : ""}`;
}

/**
 * Search the bundled sections and show ranked results.
 *
 * @param {string} query
 */
async function runSearch(query) {
    const phrase = query.trim().toLowerCase();
    if (phrase === "") {
        if (pageIndex >= 0) {
            renderCurrentPage();
        }
        return;
    }
    const token = ++renderToken;
    window.__fimHelpRendered = null;
    let index;
    let manifest;
    try {
        [index, manifest] = await Promise.all([loadSearchIndex(), loadManifest()]);
    } catch (error) {
        if (token === renderToken) {
            renderError(String(error.message), () => runSearch(query));
        }
        return;
    }
    if (token !== renderToken) {
        return;
    }
    const terms = phrase.split(/\s+/);
    const topics = new Map(manifest.topics.map((topic) => [topic.id, topic]));
    const matches = index
        .map((entry, position) => ({
            entry,
            position,
            score: scoreEntry(entry, terms, phrase, topics),
        }))
        .filter((match) => match.score > 0)
        .sort((a, b) => b.score - a.score || a.position - b.position);
    const page = element("div", "help-search-page");
    page.append(element("h1", "", "Search results"));
    page.append(
        element(
            "p",
            "",
            matches.length === 0
                ? `No Help section mentions “${query.trim()}”.`
                : `${matches.length} Help ${matches.length === 1 ? "section matches" : "sections match"} “${query.trim()}”.`
        )
    );
    const list = element("ol", "help-search-results");
    for (const { entry } of matches.slice(0, SEARCH_RESULT_LIMIT)) {
        const item = element("li");
        item.append(topicLink(entry.topic, entry.anchor, entry.heading));
        const topic = topics.get(entry.topic);
        if (topic && entry.anchor !== "") {
            item.append(element("span", "help-search-topic", topic.title));
        }
        item.append(element("p", "help-search-snippet", snippet(entry.text, terms)));
        list.append(item);
    }
    page.append(list);
    renderBreadcrumb(null, undefined, "Search results");
    helpContent.replaceChildren(page);
    helpContent.scrollTop = 0;
    window.__fimHelpRendered = "search";
}

/**
 * Show one Help topic, recording the page in Help's own history.
 *
 * @param {string} topic - A registered topic id; empty or omitted for Help home.
 * @param {string} [anchor] - A heading id to scroll to once rendered.
 */
window.fim.showHelp = function showHelp(topic, anchor) {
    captureOrigin();
    pushPage(topic ? topic : null, anchor ?? "");
    window.fim.showScreen("screen-help");
    renderCurrentPage();
};

/** Show Help home, the list of every topic. */
window.fim.showHelpHome = function showHelpHome() {
    window.fim.showHelp(null);
};

/**
 * Open the Help topic for the focused field, an open dialog, or the
 * visible screen.
 *
 * @returns {boolean} Whether a topic was opened.
 */
function openContextHelp() {
    const screenId = visibleScreenId();
    if (screenId === "screen-help") {
        window.fim.showHelpHome();
        return true;
    }
    const fieldKey = focusedFieldHelpKey();
    const fieldTopic = fieldKey === null ? undefined : FIELD_HELP_TOPICS[fieldKey];
    if (fieldTopic !== undefined) {
        window.fim.showHelp(fieldTopic.topic, fieldTopic.anchor);
        return true;
    }
    const screenTopic = SCREEN_HELP[screenId];
    if (screenTopic !== undefined) {
        window.fim.showHelp(screenTopic.topic, screenTopic.anchor);
        return true;
    }
    window.fim.showHelpHome();
    return true;
}

/**
 * Find the `FIELD_HELP` key for the focused control: its `field-<key>`
 * id, a `label[data-field-help]` for it, or its fieldset's legend.
 *
 * @returns {string|null}
 */
function focusedFieldHelpKey() {
    const focused = document.activeElement;
    if (focused === null || focused === document.body) {
        return null;
    }
    if (focused.id?.startsWith("field-")) {
        const key = focused.id.slice("field-".length);
        if (key in FIELD_HELP_TOPICS) {
            return key;
        }
    }
    for (const label of focused.labels ?? []) {
        if (label.dataset.fieldHelp) {
            return label.dataset.fieldHelp;
        }
    }
    const legend = focused.closest("fieldset")?.querySelector(":scope > legend[data-field-help]");
    return legend ? legend.dataset.fieldHelp : null;
}

window.fim.helpContext = {
    SCREEN_HELP,
    FIELD_HELP_TOPICS,
    openContextHelp,
    returnToWork,
};

helpBackButton.addEventListener("click", () => {
    if (pageIndex > 0) {
        pageIndex -= 1;
        renderCurrentPage();
    } else {
        returnToWork();
    }
});

helpForwardButton.addEventListener("click", () => {
    if (pageIndex < pages.length - 1) {
        pageIndex += 1;
        renderCurrentPage();
    }
});

helpHomeButton.addEventListener("click", () => window.fim.showHelpHome());
helpReturnButton.addEventListener("click", returnToWork);

helpScreenButton.addEventListener("click", () => {
    const screenTopic = SCREEN_HELP[origin.screenId];
    if (screenTopic !== undefined) {
        window.fim.showHelp(screenTopic.topic, screenTopic.anchor);
    }
});

helpSearch.addEventListener("input", () => {
    clearTimeout(searchTimer);
    searchTimer = setTimeout(() => runSearch(helpSearch.value), SEARCH_DEBOUNCE_MS);
});

helpSearch.addEventListener("keydown", (event) => {
    if (event.key === "Escape" && helpSearch.value !== "") {
        event.preventDefault();
        helpSearch.value = "";
        runSearch("");
    } else if (event.key === "Enter") {
        clearTimeout(searchTimer);
        runSearch(helpSearch.value);
    }
});

// F1 is ignored while a modal dialog is open: Help would appear behind
// the dialog, and the dialog's fields already show their tooltip on focus.
document.addEventListener("keydown", (event) => {
    if (event.key !== "F1" || document.querySelector("dialog[open]") !== null) {
        return;
    }
    event.preventDefault();
    openContextHelp();
});

helpBreadcrumb.addEventListener("click", (event) => {
    const link = event.target.closest("a[data-fim-help-home]");
    if (link !== null) {
        event.preventDefault();
        window.fim.showHelpHome();
    }
});

// Every generated link carries `href="#"` plus a `data-fim-*` attribute
// (`dev/bin/generate-help-html`'s link rewriting). One delegated handler
// routes every click, so no `<a>` is left to native navigation, which in
// a pywebview window can carry the whole application window away from
// `index.html` rather than open a new tab.
helpContent.addEventListener("click", async (event) => {
    const link = event.target.closest("a");
    if (link === null) {
        return;
    }
    // A same-document `#anchor` link keeps its real fragment href and
    // carries neither attribute below; the browser scrolls natively.
    if (link.dataset.fimHelp) {
        event.preventDefault();
        helpSearch.value = "";
        window.fim.showHelp(link.dataset.fimHelp, link.dataset.fimAnchor || undefined);
    } else if (link.dataset.fimExternal) {
        event.preventDefault();
        // `window.__fimHelpExternalLinkSettled` -- the same settle-flag
        // fix, and the same reason, as `run-view-controls.js`'s own
        // `onCancelClicked`: see that file for the full hazard this
        // closes.
        window.__fimHelpExternalLinkSettled = false;
        await window.pywebview.api.open_external_link(link.dataset.fimExternal);
        window.__fimHelpExternalLinkSettled = true;
    }
});
